/// Per-write options for GIF encoding.
#[derive(Clone, Debug, PartialEq)]
pub struct GifSaveOptions {
    /// Delay between frames in centiseconds (1/100 s).  0 = unspecified.
    pub delay_cs: u16,
    /// Number of times the animation should loop.  0 = loop forever.
    pub loop_count: u16,
    /// Enable blue-noise ordered dithering when mapping pixels to the palette.
    pub dither: bool,
    /// Dither strength in `[0, 1]`.  0 = no visible dithering, 1 = full.
    pub dither_strength: f32,
    /// Emit a transparent background. Pixels whose source alpha is below 50% become the GIF's transparent palette index; the rest are quantised normally. GIF transparency is 1-bit, so partially-covered (anti- aliased) edge pixels are forced fully opaque or fully transparent.
    pub transparent: bool,
}

impl Default for GifSaveOptions {
    fn default() -> Self {
        // SAFETY: `_new` always returns a live handle; freed before return.
        unsafe {
            let h = ffi::whiteout_textures_GifSaveOptions_new();
            let out = GifSaveOptions {
                delay_cs: ffi::whiteout_textures_GifSaveOptions_get_delayCs(h),
                loop_count: ffi::whiteout_textures_GifSaveOptions_get_loopCount(h),
                dither: ffi::whiteout_textures_GifSaveOptions_get_dither(h) != 0,
                dither_strength: ffi::whiteout_textures_GifSaveOptions_get_ditherStrength(h),
                transparent: ffi::whiteout_textures_GifSaveOptions_get_transparent(h) != 0,
            };
            ffi::whiteout_textures_GifSaveOptions_delete(h);
            out
        }
    }
}

impl GifSaveOptions {
    /// Build a native handle carrying these values. Caller frees it.
    #[allow(dead_code)] // consumed once the methods taking these options bind
    pub(crate) unsafe fn to_native(&self) -> *mut ffi::whiteout_GifSaveOptions {
        unsafe {
            let h = ffi::whiteout_textures_GifSaveOptions_new();
            ffi::whiteout_textures_GifSaveOptions_set_delayCs(h, self.delay_cs);
            ffi::whiteout_textures_GifSaveOptions_set_loopCount(h, self.loop_count);
            ffi::whiteout_textures_GifSaveOptions_set_dither(h, if self.dither { 1 } else { 0 });
            ffi::whiteout_textures_GifSaveOptions_set_ditherStrength(h, self.dither_strength);
            ffi::whiteout_textures_GifSaveOptions_set_transparent(
                h,
                if self.transparent { 1 } else { 0 },
            );
            h
        }
    }

    /// Free a handle produced by [`Self::to_native`].
    ///
    /// # Safety
    /// `h` must have come from `to_native` and not been freed already.
    #[allow(dead_code)]
    pub(crate) unsafe fn free_native(h: *mut ffi::whiteout_GifSaveOptions) {
        unsafe { ffi::whiteout_textures_GifSaveOptions_delete(h) }
    }
}

